-- SQLite schema v1: human chronology and geological time are separate domains.
CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, name TEXT NOT NULL, sha256 TEXT NOT NULL, applied_at TEXT NOT NULL);
CREATE TABLE licenses(license_id TEXT PRIMARY KEY, label TEXT NOT NULL, url TEXT, commercial_allowed INTEGER CHECK(commercial_allowed IN(0,1)), attribution_required INTEGER NOT NULL DEFAULT 0 CHECK(attribution_required IN(0,1)));
CREATE TABLE cultures(id TEXT PRIMARY KEY, parent_id TEXT REFERENCES cultures(id), label TEXT NOT NULL, external_id TEXT, authority_url TEXT);
CREATE TABLE historical_periods(id TEXT PRIMARY KEY, parent_id TEXT REFERENCES historical_periods(id), label TEXT NOT NULL, external_id TEXT, authority_url TEXT);
CREATE TABLE geological_periods(id TEXT PRIMARY KEY, parent_id TEXT REFERENCES geological_periods(id), label TEXT NOT NULL, external_id TEXT, authority_url TEXT);
CREATE TABLE regions(id TEXT PRIMARY KEY, parent_id TEXT REFERENCES regions(id), label TEXT NOT NULL, external_id TEXT, authority_url TEXT);
CREATE TABLE locations(id TEXT PRIMARY KEY, parent_id TEXT REFERENCES locations(id), label TEXT NOT NULL, external_id TEXT, authority_url TEXT);
CREATE TABLE object_categories(id TEXT PRIMARY KEY, parent_id TEXT REFERENCES object_categories(id), label TEXT NOT NULL, external_id TEXT, authority_url TEXT);
CREATE TABLE materials(id TEXT PRIMARY KEY, parent_id TEXT REFERENCES materials(id), label TEXT NOT NULL, external_id TEXT, authority_url TEXT);
CREATE TABLE techniques(id TEXT PRIMARY KEY, parent_id TEXT REFERENCES techniques(id), label TEXT NOT NULL, external_id TEXT, authority_url TEXT);
CREATE TABLE taxa(id TEXT PRIMARY KEY, parent_id TEXT REFERENCES taxa(id), label TEXT NOT NULL, external_id TEXT, authority_url TEXT);
CREATE TABLE formations(id TEXT PRIMARY KEY, parent_id TEXT REFERENCES formations(id), label TEXT NOT NULL, external_id TEXT, authority_url TEXT);
CREATE TABLE institutions(id TEXT PRIMARY KEY, parent_id TEXT REFERENCES institutions(id), label TEXT NOT NULL, external_id TEXT, authority_url TEXT);
CREATE TABLE vocab_names(vocab TEXT NOT NULL, term_id TEXT NOT NULL, language TEXT NOT NULL, name_type TEXT NOT NULL, value TEXT NOT NULL, PRIMARY KEY(vocab,term_id,language,name_type,value));
CREATE TABLE human_chronology(period_id TEXT PRIMARY KEY REFERENCES historical_periods(id), year_start INTEGER, year_end INTEGER, calendar TEXT NOT NULL DEFAULT 'astronomical_proleptic_gregorian', uncertainty TEXT, CHECK(year_start IS NULL OR year_end IS NULL OR year_start<=year_end));
CREATE TABLE geological_timescale(period_id TEXT PRIMARY KEY REFERENCES geological_periods(id), rank TEXT NOT NULL CHECK(rank IN('EON','ERA','PERIOD','EPOCH','AGE')), age_min_ma REAL CHECK(age_min_ma>=0), age_max_ma REAL CHECK(age_max_ma>=0), scale_version TEXT NOT NULL, CHECK(age_min_ma IS NULL OR age_max_ma IS NULL OR age_min_ma<=age_max_ma));
CREATE TABLE location_details(location_id TEXT PRIMARY KEY REFERENCES locations(id), region_id TEXT REFERENCES regions(id), latitude REAL CHECK(latitude BETWEEN -90 AND 90), longitude REAL CHECK(longitude BETWEEN -180 AND 180));
CREATE TABLE taxon_details(taxon_id TEXT PRIMARY KEY REFERENCES taxa(id), scientific_name TEXT NOT NULL, rank TEXT, named_year INTEGER, identification_notes TEXT);
CREATE TABLE sources(source_id TEXT PRIMARY KEY, institution_id TEXT REFERENCES institutions(id), adapter TEXT NOT NULL, base_url TEXT NOT NULL, terms_url TEXT NOT NULL, license_id TEXT REFERENCES licenses(license_id), last_checked TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('APPROVED','PER_RECORD','RESEARCH_ONLY')), notes TEXT NOT NULL);
CREATE TABLE collection_objects(object_id TEXT PRIMARY KEY, object_kind TEXT NOT NULL CHECK(object_kind IN('CULTURAL_HERITAGE','NATURAL_HISTORY')), category_id TEXT NOT NULL REFERENCES object_categories(id), primary_name TEXT NOT NULL CHECK(length(trim(primary_name))>0), description TEXT, museum_id TEXT REFERENCES institutions(id), accession_number TEXT, origin_location_id TEXT REFERENCES locations(id), discovery_location_id TEXT REFERENCES locations(id), license_status TEXT NOT NULL REFERENCES licenses(license_id), verification_status TEXT NOT NULL CHECK(verification_status IN('SOURCE_VERIFIED','NEEDS_REVIEW','CURATOR_VERIFIED')), translation_status TEXT NOT NULL DEFAULT 'pending' CHECK(translation_status IN('pending','source_available','curated')), editor_locked INTEGER NOT NULL DEFAULT 0 CHECK(editor_locked IN(0,1)));
CREATE INDEX object_museum_accession ON collection_objects(museum_id,accession_number);
CREATE INDEX object_kind_category ON collection_objects(object_kind,category_id);
CREATE INDEX object_quality ON collection_objects(verification_status,license_status);
CREATE INDEX object_origin ON collection_objects(origin_location_id);
CREATE INDEX object_discovery ON collection_objects(discovery_location_id);
CREATE TABLE source_records(source_id TEXT NOT NULL REFERENCES sources(source_id), record_id TEXT NOT NULL, object_id TEXT REFERENCES collection_objects(object_id), record_url TEXT NOT NULL, dataset_url TEXT, license_id TEXT NOT NULL REFERENCES licenses(license_id), copyright_notice TEXT NOT NULL, fetched_at TEXT NOT NULL, checked_at TEXT NOT NULL, commercial_allowed INTEGER CHECK(commercial_allowed IN(0,1)), payload_sha256 TEXT NOT NULL, raw_json TEXT NOT NULL CHECK(json_valid(raw_json)), PRIMARY KEY(source_id,record_id));
CREATE INDEX source_object ON source_records(object_id);
CREATE TABLE field_evidence(object_id TEXT NOT NULL REFERENCES collection_objects(object_id), field_path TEXT NOT NULL, source_id TEXT NOT NULL, record_id TEXT NOT NULL, source_value TEXT, status TEXT NOT NULL CHECK(status IN('MATCHED','UNKNOWN','CONFLICT','CURATED')), PRIMARY KEY(object_id,field_path,source_id,record_id), FOREIGN KEY(source_id,record_id) REFERENCES source_records(source_id,record_id));
CREATE TABLE object_names(object_id TEXT NOT NULL REFERENCES collection_objects(object_id), language TEXT NOT NULL, name_type TEXT NOT NULL CHECK(name_type IN('PRIMARY','ORIGINAL','SCIENTIFIC','ALIAS','FORMER')), value TEXT NOT NULL, translation_status TEXT NOT NULL CHECK(translation_status IN('pending','source_available','curated')), curator_locked INTEGER NOT NULL DEFAULT 0 CHECK(curator_locked IN(0,1)), source_id TEXT, record_id TEXT, PRIMARY KEY(object_id,language,name_type,value), FOREIGN KEY(source_id,record_id) REFERENCES source_records(source_id,record_id));
CREATE INDEX names_lookup ON object_names(value,language);
CREATE TABLE cultural_heritage(object_id TEXT PRIMARY KEY REFERENCES collection_objects(object_id), historical_period_id TEXT REFERENCES historical_periods(id), year_start INTEGER, year_end INTEGER, date_label TEXT, calendar TEXT DEFAULT 'astronomical_proleptic_gregorian', date_uncertainty TEXT, creation_place_id TEXT REFERENCES locations(id), findspot_id TEXT REFERENCES locations(id), artifact_type_id TEXT REFERENCES object_categories(id), inscriptions TEXT, historical_context TEXT, interpretation TEXT, CHECK(year_start IS NULL OR year_end IS NULL OR year_start<=year_end));
CREATE TABLE occurrences(occurrence_id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(source_id), source_record_id TEXT NOT NULL, taxon_id TEXT REFERENCES taxa(id), locality_id TEXT REFERENCES locations(id), formation_id TEXT REFERENCES formations(id), basis_of_record TEXT NOT NULL, record_url TEXT NOT NULL);
CREATE TABLE fossil_specimens(object_id TEXT PRIMARY KEY REFERENCES collection_objects(object_id), scientific_name TEXT, taxon_id TEXT REFERENCES taxa(id), taxonomic_rank TEXT, geological_period_id TEXT REFERENCES geological_periods(id), formation_id TEXT REFERENCES formations(id), age_min_ma REAL CHECK(age_min_ma>=0), age_max_ma REAL CHECK(age_max_ma>=0), preserved_element TEXT, preservation_type TEXT, completeness TEXT, identification_confidence TEXT, discovery_location_id TEXT REFERENCES locations(id), discovery_year INTEGER, occurrence_id TEXT REFERENCES occurrences(occurrence_id), CHECK(age_min_ma IS NULL OR age_max_ma IS NULL OR age_min_ma<=age_max_ma));
CREATE TABLE mineral_specimens(object_id TEXT PRIMARY KEY REFERENCES collection_objects(object_id), mineral_name TEXT, classification TEXT, chemical_composition TEXT, crystal_system TEXT, origin_location_id TEXT REFERENCES locations(id), crystal_habit TEXT);
CREATE TABLE meteorite_specimens(object_id TEXT PRIMARY KEY REFERENCES collection_objects(object_id), official_name TEXT, classification TEXT, fall_date TEXT, discovery_date TEXT, discovery_location_id TEXT REFERENCES locations(id), specimen_type TEXT);
CREATE TABLE rock_specimens(object_id TEXT PRIMARY KEY REFERENCES collection_objects(object_id), lithology TEXT, geological_setting TEXT, origin_location_id TEXT REFERENCES locations(id));
CREATE TABLE biological_specimens(object_id TEXT PRIMARY KEY REFERENCES collection_objects(object_id), scientific_name TEXT, taxon_id TEXT REFERENCES taxa(id), collecting_location_id TEXT REFERENCES locations(id), collecting_date TEXT);
CREATE TABLE geological_specimens(object_id TEXT PRIMARY KEY REFERENCES collection_objects(object_id), geological_period_id TEXT REFERENCES geological_periods(id), formation_id TEXT REFERENCES formations(id));
CREATE TABLE measurements(object_id TEXT NOT NULL REFERENCES collection_objects(object_id), dimension TEXT NOT NULL, value REAL, unit TEXT, verbatim TEXT NOT NULL, source_id TEXT, record_id TEXT, PRIMARY KEY(object_id,dimension,verbatim), FOREIGN KEY(source_id,record_id) REFERENCES source_records(source_id,record_id));
CREATE TABLE media(media_id TEXT PRIMARY KEY, object_id TEXT NOT NULL REFERENCES collection_objects(object_id), media_kind TEXT NOT NULL CHECK(media_kind IN('IMAGE','MODEL')), url TEXT NOT NULL, license_id TEXT NOT NULL REFERENCES licenses(license_id), commercial_allowed INTEGER CHECK(commercial_allowed IN(0,1)), verification_status TEXT NOT NULL CHECK(verification_status IN('UNVERIFIED','VERIFIED','DENIED')), copyright_notice TEXT NOT NULL, attribution TEXT, terms_url TEXT NOT NULL, checked_at TEXT, source_id TEXT NOT NULL, record_id TEXT NOT NULL, FOREIGN KEY(source_id,record_id) REFERENCES source_records(source_id,record_id));
CREATE INDEX media_object_license ON media(object_id,license_id,verification_status);
CREATE TABLE duplicate_candidates(first_object_id TEXT NOT NULL REFERENCES collection_objects(object_id), second_object_id TEXT NOT NULL REFERENCES collection_objects(object_id), reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING', PRIMARY KEY(first_object_id,second_object_id,reason));
CREATE TABLE import_runs(run_id INTEGER PRIMARY KEY, source_id TEXT REFERENCES sources(source_id), started_at TEXT NOT NULL, finished_at TEXT, succeeded INTEGER DEFAULT 0, skipped INTEGER DEFAULT 0, duplicates INTEGER DEFAULT 0, errors INTEGER DEFAULT 0, unknown_license INTEGER DEFAULT 0);
CREATE TABLE import_errors(run_id INTEGER NOT NULL REFERENCES import_runs(run_id), record_id TEXT, message TEXT NOT NULL);
CREATE TABLE object_cultures(object_id TEXT NOT NULL REFERENCES collection_objects(object_id), term_id TEXT NOT NULL REFERENCES cultures(id), PRIMARY KEY(object_id,term_id));
CREATE INDEX cultures_object ON object_cultures(term_id,object_id);
CREATE TABLE object_materials(object_id TEXT NOT NULL REFERENCES collection_objects(object_id), term_id TEXT NOT NULL REFERENCES materials(id), PRIMARY KEY(object_id,term_id));
CREATE INDEX materials_object ON object_materials(term_id,object_id);
CREATE TABLE object_techniques(object_id TEXT NOT NULL REFERENCES collection_objects(object_id), term_id TEXT NOT NULL REFERENCES techniques(id), PRIMARY KEY(object_id,term_id));
CREATE INDEX techniques_object ON object_techniques(term_id,object_id);
CREATE TRIGGER cultural_heritage_kind BEFORE INSERT ON cultural_heritage WHEN (SELECT object_kind FROM collection_objects WHERE object_id=NEW.object_id)!='CULTURAL_HERITAGE' BEGIN SELECT RAISE(ABORT,'extension object kind mismatch'); END;
CREATE TRIGGER fossil_specimens_kind BEFORE INSERT ON fossil_specimens WHEN (SELECT object_kind FROM collection_objects WHERE object_id=NEW.object_id)!='NATURAL_HISTORY' BEGIN SELECT RAISE(ABORT,'extension object kind mismatch'); END;
CREATE TRIGGER mineral_specimens_kind BEFORE INSERT ON mineral_specimens WHEN (SELECT object_kind FROM collection_objects WHERE object_id=NEW.object_id)!='NATURAL_HISTORY' BEGIN SELECT RAISE(ABORT,'extension object kind mismatch'); END;
CREATE TRIGGER meteorite_specimens_kind BEFORE INSERT ON meteorite_specimens WHEN (SELECT object_kind FROM collection_objects WHERE object_id=NEW.object_id)!='NATURAL_HISTORY' BEGIN SELECT RAISE(ABORT,'extension object kind mismatch'); END;
CREATE TRIGGER rock_specimens_kind BEFORE INSERT ON rock_specimens WHEN (SELECT object_kind FROM collection_objects WHERE object_id=NEW.object_id)!='NATURAL_HISTORY' BEGIN SELECT RAISE(ABORT,'extension object kind mismatch'); END;
CREATE TRIGGER biological_specimens_kind BEFORE INSERT ON biological_specimens WHEN (SELECT object_kind FROM collection_objects WHERE object_id=NEW.object_id)!='NATURAL_HISTORY' BEGIN SELECT RAISE(ABORT,'extension object kind mismatch'); END;
CREATE TRIGGER geological_specimens_kind BEFORE INSERT ON geological_specimens WHEN (SELECT object_kind FROM collection_objects WHERE object_id=NEW.object_id)!='NATURAL_HISTORY' BEGIN SELECT RAISE(ABORT,'extension object kind mismatch'); END;
CREATE VIRTUAL TABLE catalogue_fts USING fts5(object_id UNINDEXED, names, description, tokenize='unicode61');
